create table public.skill_families(id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null);
create table public.skills(id uuid primary key default gen_random_uuid(), family_id uuid not null references public.skill_families, slug text unique not null, name text not null);
create table public.skill_edges(from_skill_id uuid references public.skills on delete cascade, to_skill_id uuid references public.skills on delete cascade, relation text not null, primary key(from_skill_id,to_skill_id));
create table public.project_templates(id uuid primary key default gen_random_uuid(), skill_id uuid references public.skills, role_text text, level text not null, title text not null, brief jsonb not null, active boolean not null default true);
create table public.submissions(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students on delete cascade, template_id uuid references public.project_templates, title text not null, status text not null default 'draft' check(status in ('draft','submitted','auditing','scored','needs_review','failed','appealed')), claimed_skill_ids uuid[] not null default '{}', video_path text, video_url text, video_seconds int, video_bytes bigint, originality_answers jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audits(id uuid primary key default gen_random_uuid(), submission_id uuid not null references public.submissions on delete cascade, rubric_version text not null, prompt_version text not null, overall_score numeric, confidence numeric, summary text, rubric jsonb not null default '[]', evidence jsonb not null default '[]', transcript jsonb, visual_observations jsonb, next_steps text[] not null default '{}', review_status text not null default 'unreviewed', reviewed_by uuid references auth.users, created_at timestamptz not null default now());
create table public.skill_scores(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students on delete cascade, skill_id uuid not null references public.skills, score numeric not null check(score between 0 and 100), level text not null, verified boolean not null default false, pending_review boolean not null default false, share_ok boolean not null default true, audit_id uuid references public.audits, updated_at timestamptz not null default now(), unique(student_id,skill_id));
create table public.skill_score_history(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students, skill_id uuid not null references public.skills, score numeric not null, level text not null, verified boolean not null, audit_id uuid references public.audits, created_at timestamptz not null default now());
create table public.project_assignments(id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students on delete cascade, template_id uuid references public.project_templates, status text not null default 'assigned', brief jsonb not null, created_at timestamptz not null default now());
create table public.agent_runs(id uuid primary key default gen_random_uuid(), submission_id uuid references public.submissions on delete cascade, user_id uuid references auth.users, stage text not null default 'received' check(stage in ('received','reading','watching','scoring','writing','done')), attempt int not null default 1, mode text not null default 'mock', status text not null default 'queued', latency_ms int, token_estimate int, error_code text, created_at timestamptz not null default now());
create table public.tickets(id uuid primary key default gen_random_uuid(), submission_id uuid not null references public.submissions on delete cascade, student_id uuid not null references public.students, reason text not null, status text not null default 'open', assigned_to uuid references auth.users, decision text, created_at timestamptz not null default now(), resolved_at timestamptz);
create unique index one_open_ticket_per_submission on public.tickets(submission_id) where status in ('open','assigned');
create table public.rubric_feedback_log(id uuid primary key default gen_random_uuid(), ticket_id uuid references public.tickets, criterion text not null, outcome text not null, note text, created_at timestamptz not null default now());

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['skill_families','skills','skill_edges','project_templates','submissions','audits','skill_scores','skill_score_history','project_assignments','agent_runs','tickets','rubric_feedback_log'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
-- No broad grants here; subsequent policy migrations grant only explicitly authorized operations.
